C={'三件装':8000,'单件装':5000,'散装':4300}
rows=[]
for an,a in A.items():
  for bn,b in B.items():
    for cn,c in C.items():
      s=a+b+c
      d209=3000 if s>=21900 else 0
      d249=5500 if s>=25400 else 0
      pct=s*10//100 if s>=10000 else 0
      total=s-d209-d249-pct
      rows.append((total,s,an,bn,cn,d209,d249,pct))
rows.sort()
for r in rows:
  print(f"total={r[0]/100:7.2f} sub={r[1]/100:7.2f} A={r[2]:4s} B={r[3]:3s} C={r[4]:4s} c209={r[5]/100:5.2f} c249={r[6]/100:5.2f} pct={r[7]/100:6.2f}")
PY

